(window.webpackJsonpGUI=window.webpackJsonpGUI||[]).push([[149],{1488:function(t,e,p){"use strict";p.r(e),e.default={code:"114TCPJ09",title:"114-澎湖縣國中（競賽模式）",unlockCode:"114TCPJ09",tasks:[{id:"114TCPJ09-1",code:"114TCPJ09-114TCPJ09-1",title:"神秘留言解碼器",description:"每個人會收到一段被編碼的英文字母訊息，訊息中只有小寫字母與空白。解碼規則：每個英文字母向前移動一個字母（例如 b→a，c→b，…，a→z），空白保持不變。請讀入一段編碼後的字串，輸出正確解碼後的內容。",examples:[{input:"bqqmf",output:"apple",explanation:"b→a, q→p, q→p, m→l, f→e，組合起來是 apple。"},{input:"ifmmp xpsme",output:"hello world",explanation:"ifmmp 解碼為 hello，xpsme 解碼為 world，空白保持不變。"}],testCases:[{input:"bqqmf",expectedOutput:"apple",score:10},{input:"ifmmp xpsme",expectedOutput:"hello world",score:10},{input:"zoo",expectedOutput:"ynn",score:10},{input:"uif dpef jt gvo",expectedOutput:"the code is fun",score:10},{input:"ibwf b ojdf ebz",expectedOutput:"have a nice day",score:10}],difficulty:"L2",sb3Path:null},{id:"114TCPJ09-2",code:"114TCPJ09-114TCPJ09-2",title:"剛好的禮券",description:"小華手上有一張金額固定的禮券，想在商店中正好買兩樣不同的商品，將禮券金額完全花光。請檢查是否能從商品價格清單中找到兩個不同位置的商品，價格總和恰好等於禮券面額。如果找得到，輸出這兩個商品的價格（小的在前，大的在後）；如果同時有多組組合符合，輸出價差最小的兩樣商品價格；找不到則輸出 No Solution。",examples:[{input:"3 10\n1 2 3",output:"No Solution",explanation:"任兩數相加都不等於 10。"},{input:"5 100\n20 40 50 60 80",output:"40 60",explanation:"20+80=100 與 40+60=100 都符合，但 40 與 60 價差 20 小於 20 與 80 價差 60，故輸出 40 60。"}],testCases:[{input:"3 10\n1 2 3",expectedOutput:"No Solution",score:10},{input:"5 100\n20 40 50 60 80",expectedOutput:"40 60",score:10},{input:"4 50\n10 20 30 40",expectedOutput:"20 30",score:10},{input:"2 20\n10 10",expectedOutput:"10 10",score:10},{input:"5 15\n1 2 3 4 5",expectedOutput:"No Solution",score:10}],difficulty:"L3",sb3Path:null},{id:"114TCPJ09-3",code:"114TCPJ09-114TCPJ09-3",title:"細胞分裂模擬",description:"某種細胞第 1 天有 0 個，第 2 天有 1 個，第 3 天開始，每一天的細胞數量都是「前一天」加上「前前一天」的數量之和。請列出從第 1 天到第 n 天每天的細胞數量。",examples:[{input:"5",output:"0 1 1 2 3",explanation:"第1天0、第2天1，之後每天等於前兩天之和：1=0+1、2=1+1、3=1+2。"}],testCases:[{input:"2",expectedOutput:"0 1",score:10},{input:"3",expectedOutput:"0 1 1",score:10},{input:"5",expectedOutput:"0 1 1 2 3",score:10},{input:"6",expectedOutput:"0 1 1 2 3 5",score:10},{input:"7",expectedOutput:"0 1 1 2 3 5 8",score:10}],difficulty:"L2",sb3Path:null},{id:"114TCPJ09-4",code:"114TCPJ09-114TCPJ09-4",title:"分組報告",description:"電腦課要同學分組做期末報告，分組方式為依座號順序，每 3 個人一組（1,2,3 為第一組，4,5,6 為第二組……以此類推）。輸入同學的座號，請判斷他在哪一組。",examples:[{input:"7",output:"3",explanation:"7 號屬於第 3 組（7,8,9 為第三組）。"}],testCases:[{input:"7",expectedOutput:"3",score:10},{input:"1",expectedOutput:"1",score:10},{input:"2",expectedOutput:"1",score:10},{input:"98",expectedOutput:"33",score:10},{input:"99",expectedOutput:"33",score:10},{input:"100",expectedOutput:"34",score:10}],difficulty:"L2",sb3Path:null},{id:"114TCPJ09-5",code:"114TCPJ09-114TCPJ09-5",title:"購買紀念品",description:"小明想要盡量把身上剩下的日幣都花完，來買到最多件紀念品。請寫一個程式，判斷在不超過剩餘日幣的情況下，最多可以買到幾件紀念品（依商品單價由低到高依序購買，並受限於各商品的剩餘數量）。",examples:[{input:"1000\n3\n100 300 200\n3 4 2",output:"6",explanation:"先買 3 個 100 元、2 個 200 元、1 個 300 元，共花 1000 元，買到 6 件。"},{input:"500\n4\n600 700 800\n3 4 5",output:"0",explanation:"剩下的錢不夠買任何一樣商品，最多買 0 件。"}],testCases:[{input:"1000\n3\n100 300 200\n3 4 2",expectedOutput:"6",score:8},{input:"500\n4\n600 700 800\n3 4 5",expectedOutput:"0",score:8},{input:"1500\n3\n200 300 100\n2 1 4",expectedOutput:"7",score:8},{input:"1285\n3\n400 300 100\n4 6 3",expectedOutput:"6",score:8},{input:"1500\n3\n200 100 1000\n3 2 4",expectedOutput:"5",score:8},{input:"100\n4\n400 200 300 500\n3 5 4 2",expectedOutput:"0",score:8},{input:"1500\n4\n30 20 10 50\n1 1 3 1",expectedOutput:"6",score:8},{input:"50\n3\n200 100 300\n4 3 5",expectedOutput:"0",score:8},{input:"1800\n4\n100 300 200 400\n6 4 8 2",expectedOutput:"12",score:8}],difficulty:"L3",sb3Path:null}]}}}]);